  static DataGrid Grid(string name,int height){var grid=new DataGrid{AutoGenerateColumns=false,CanUserAddRows=false,CanUserDeleteRows=false,IsReadOnly=true,SelectionMode=DataGridSelectionMode.Single,Height=height,MinHeight=100,HeadersVisibility=DataGridHeadersVisibility.Column};System.Windows.Automation.AutomationProperties.SetName(grid,name);return grid;}
  static DataGridTextColumn TextColumn(string title,string binding,int weight){return new DataGridTextColumn{Header=title,Binding=new Binding(binding),Width=new DataGridLength(weight,DataGridLengthUnitType.Star)};}
  static void Accent(Button button){Theme.Bind(button,Control.BackgroundProperty,"Accent");Theme.Bind(button,Control.ForegroundProperty,"AccentText");}
  // Only the saved preferences network imports read are shown inline; originals, solving and matching are fixed for telescope downloads.
  CheckBox Filter(Panel parent,string text,bool value){var box=new CheckBox{Content=text,IsChecked=value,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,8,4)};System.Windows.Automation.AutomationProperties.SetName(box,text);UiHelp.Hint(box,"Saved import preference. Also applies to folder, USB and Dump imports; running imports keep their settings.");RoutedEventHandler changed=(s,e)=>FiltersChanged();box.Checked+=changed;box.Unchecked+=changed;parent.Children.Add(box);return box;}
  void FiltersChanged(){
   if(SkipFailed==null||SkipRaster==null)return;filters.IgnoreFailed=SkipFailed.IsChecked==true;filters.IgnoreRaster=SkipRaster.IsChecked==true;if(filters.Changed!=null)filters.Changed(filters);
   foreach(var path in basket.Keys.Where(p=>!include(basket[p])).ToList())basket.Remove(path);if(listed!=null)ShowFiles(listed);UpdateActions();
  }
  Button Button(Panel parent,string text,Action action){var button=new Button{Content=text,Margin=new Thickness(0,0,8,4)};System.Windows.Automation.AutomationProperties.SetName(button,text);UiHelp.For(button,text);button.Click+=(s,e)=>{if(!busy)action();};parent.Children.Add(button);return button;}
  async Task<DiscoveryResult> FindOnNetworks(CancellationToken ct){
   var networks=selectedNetwork==null?DiscoveryNetwork.Available():new List<DiscoveryNetwork>{selectedNetwork};if(networks.Count==0)throw new IOException("Connect this PC to the telescope's Wi-Fi or your shared LAN, then search again.");
   var found=await Task.WhenAll(networks.Select(n=>Task.Run(()=>TelescopeDiscovery.Find(n,ct),ct)));var result=new DiscoveryResult();foreach(var r in found){result.Warnings.AddRange(r.Warnings);result.Devices.AddRange(r.Devices);}var unique=result.Devices.GroupBy(d=>d.Kind+"|"+d.Host).Select(g=>g.First()).OrderBy(d=>d.Name).ToList();result.Devices.Clear();result.Devices.AddRange(unique);return result;
  }
  async Task Operation(Func<CancellationToken,Task> work,string status){if(busy)return;busy=true;Error.Text="";Status.Text=status;operation=new CancellationTokenSource();UpdateActions();try{await work(operation.Token);}catch(OperationCanceledException){if(!closed)Status.Text="Cancelled. You can search or connect again.";}catch(Exception e){if(!closed){Error.Text=e.Message;Status.Text="Could not complete this step.";}}finally{operation.Dispose();operation=null;busy=false;if(!closed)UpdateActions();}}
  internal async Task Discover(){await Operation(async ct=>{Devices.ItemsSource=null;var result=await discovery(ct);if(closed)return;Devices.ItemsSource=result.Devices;Devices.SelectedItem=result.Devices.Count==1?result.Devices[0]:null;Status.Text=result.Devices.Count==0?"No telescopes replied. Check that both devices share the same network. Search again, or open Advanced for manual access.":result.Devices.Count+" telescope(s) found. Select yours and connect.";if(result.Warnings.Count>0)Error.Text=string.Join("\n",result.Warnings.Distinct());},"Finding telescopes on your networks… (about 8 seconds)");}
  internal async Task ConnectSelected(){var selected=Devices.SelectedItem as DiscoveredTelescope;if(selected==null)return;var c=new RemoteConnection{Kind=selected.Kind,Host=selected.Host,Folder=selected.Kind=="Seestar SMB"?@"\\"+selected.Host+@"\EMMC Images":"/",IncludeExisting=includeExisting,PollSeconds=poll,LimitMB=limit,Port=ftpPort,User=ftpUser,Password=ftpPassword};await Connect(selected,c);}
  internal async Task Connect(DiscoveredTelescope selected,RemoteConnection c){await Operation(async ct=>{c.Validate(false);var listing=await Task.Run(()=>{using(var source=sourceFactory(c))return RemoteCaptureCatalog.Browse(source,c,c.Folder,ct);},ct);if(closed)return;ResetSelection();connection=c;device=selected;folder=c.Folder;firstListing=listing;DiscoveryPanel.Visibility=Visibility.Collapsed;ConnectedPanel.Visibility=Visibility.Visible;BrowserPanel.Visibility=Visibility.Collapsed;syncing=true;try{Files.ItemsSource=null;}finally{syncing=false;}searchAll=false;ConnectedText.Text="Connected · "+selected.Name+" · "+c.Host;Status.Text="Choose files, search all captures, or start live import."+(c.Kind=="Seestar SMB"?" Enable Save Each Frame in Seestar to save individual exposures.":"");FolderText.Text="Live folder: All captures";ConfigureProfile(selected);},"Connecting to "+selected.Name+"…");}
  void ConfigureProfile(DiscoveredTelescope selected){string make=selected.Kind=="Seestar SMB"?"Seestar":"DWARFLAB";var choices=new List<TelescopeProfile>{new TelescopeProfile{Model="Auto"}};// Saved telescopes of this make first, then any whose make is unrecorded; another make's telescope is never offered.
   choices.AddRange(saved.Where(p=>TelescopeProfiles.Make(p)==make).OrderBy(p=>p.Id,StringComparer.OrdinalIgnoreCase));choices.AddRange(saved.Where(p=>TelescopeProfiles.Make(p)=="Unknown").OrderBy(p=>p.Id,StringComparer.OrdinalIgnoreCase));Profiles.ItemsSource=choices;var bound=choices.FirstOrDefault(p=>!string.IsNullOrEmpty(selected.Identity)&&p.RemoteIdentity==selected.Identity&&p.SourceMake==make);var compatible=choices.FirstOrDefault(p=>preferred!=null&&p.Id==preferred.Id&&(string.IsNullOrEmpty(selected.Identity)||string.IsNullOrEmpty(p.RemoteIdentity)||p.RemoteIdentity==selected.Identity));Profiles.SelectedItem=bound??compatible??choices[0];string suggested=Util.Safe(selected.Name);if(saved.Any(p=>p.Id.Equals(suggested,StringComparison.OrdinalIgnoreCase))){int n=2;while(saved.Any(p=>p.Id.Equals(suggested+" "+n,StringComparison.OrdinalIgnoreCase)))n++;suggested+=" "+n;}Name.Text=suggested;}
  internal async Task Browse(string target){if(connection==null)return;await Operation(async ct=>{List<Entry> list;if(firstListing!=null&&target==connection.Folder){list=firstListing;firstListing=null;}else list=await Task.Run(()=>{using(var source=sourceFactory(connection))return RemoteCaptureCatalog.Browse(source,connection,target,ct);},ct);if(closed)return;folder=target;searchAll=false;ShowFiles(list);Status.Text="Click to select files or folders; Ctrl or Shift adds more. Double-click a folder to open it. Selections are kept as you move between folders.";},"Reading capture folders…");}
  internal async Task Search(){if(connection==null)return;await Operation(async ct=>{var list=await Task.Run(()=>{using(var source=sourceFactory(connection))return RemoteCaptureCatalog.Search(source,connection,connection.Folder,ct);},ct);if(closed)return;folder=connection.Folder;searchAll=true;basket.Clear();folders.Clear();foreach(var entry in list.Where(include))basket[entry.Path]=entry;ShowFiles(list);int found=list.Count(include);Status.Text=found==0?"No supported captures were found. Open Advanced to check the storage location.":found.ToString("N0")+" capture files found. Review the selection before importing.";},"Searching all capture folders…");}
  // listed keeps the unfiltered entries so clearing a filter can show captures it hid.
  void ShowFiles(IEnumerable<Entry> entries){listed=entries.ToList();var rows=listed.Where(e=>e.Directory||include(e)).Select(e=>new RemoteCaptureRow{Entry=e,Location=Path.GetDirectoryName(RemoteCapturePaths.Relative(connection,e.Path))??""}).ToList();
   // Replacing the rows makes the grid report the old ones as deselected; that must not drop them from the selection.
   syncing=true;try{Files.ItemsSource=rows;}finally{syncing=false;}SyncGrid();BrowserPanel.Visibility=Visibility.Visible;FolderText.Text=searchAll?"All captures":folder==connection.Folder?"All captures":RemoteCapturePaths.Relative(connection,folder);}
  // Shows the part of the selection that lies in the current listing as highlighted rows.
  void SyncGrid(){var rows=(Files.ItemsSource as IEnumerable<RemoteCaptureRow>)??Enumerable.Empty<RemoteCaptureRow>();syncing=true;try{Files.SelectedItems.Clear();foreach(var row in rows){if(row.Entry.Directory)row.Size=FolderSize(row.Entry.Path);if(Chosen(row.Entry))Files.SelectedItems.Add(row);}}finally{syncing=false;}}
  bool Chosen(Entry entry){return entry.Directory?folders.ContainsKey(entry.Path):basket.ContainsKey(entry.Path);}
  void Select(Entry entry){if(entry.Directory){folders[entry.Path]=entry;QueueCount(entry.Path);}else if(include(entry))basket[entry.Path]=entry;}
  void Unselect(Entry entry){if(entry.Directory){folders.Remove(entry.Path);if(folderErrors.Remove(entry.Path))folderContents.Remove(entry.Path);}else basket.Remove(entry.Path);}
  void RestoreClick(){if(clickFiles==null)return;basket.Clear();foreach(var p in clickFiles)basket[p.Key]=p.Value;folders.Clear();foreach(var p in clickFolders)folders[p.Key]=p.Value;clickFiles=clickFolders=null;}
  internal void ClearSelection(){basket.Clear();folders.Clear();clickFiles=clickFolders=null;SyncGrid();UpdateActions();}
  void ResetSelection(){countCancel.Cancel();countCancel=new CancellationTokenSource();pendingCounts.Clear();folderContents.Clear();folderErrors.Clear();basket.Clear();folders.Clear();clickFiles=clickFolders=null;}
  string FolderSize(string path){List<Entry> files;if(folderErrors.ContainsKey(path))return "Couldn't read";if(!folderContents.TryGetValue(path,out files))return folders.ContainsKey(path)?"Counting…":"Folder";var shown=files.Where(include).ToList();return shown.Count.ToString("N0")+" file"+(shown.Count==1?"":"s")+" · "+ImportWorkflow.Size(shown.Sum(e=>Math.Max(0,e.Size)));}
  static string Inside(RemoteConnection c,string folderPath){return folderPath.TrimEnd('\\','/')+(c.Kind=="Seestar SMB"?"\\":"/");}
  void QueueCount(string path){
   if(folderContents.ContainsKey(path)||pendingCounts.Contains(path))return;
   // A folder inside one already counted needs no second listing.
   var parent=folderContents.FirstOrDefault(p=>!folderErrors.ContainsKey(p.Key)&&path.StartsWith(Inside(connection,p.Key),StringComparison.OrdinalIgnoreCase));if(parent.Value!=null){string prefix=Inside(connection,path);folderContents[path]=parent.Value.Where(e=>e.Path.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)).ToList();return;}
   pendingCounts.Enqueue(path);if(!counting)CountFolders();
  }
  async void CountFolders(){
   counting=true;var c=connection;var ct=countCancel.Token;UpdateActions();
   try{while(pendingCounts.Count>0&&!closed&&c==connection){string path=pendingCounts.Dequeue();if(!folders.ContainsKey(path)||folderContents.ContainsKey(path))continue;
     // Let a double-click that only opens the folder undo the selection before listing its whole tree.
     try{await Task.Delay(500,ct);}catch(OperationCanceledException){return;}if(c!=connection||!folders.ContainsKey(path)||folderContents.ContainsKey(path))continue;
     try{var files=await Task.Run(()=>{using(var source=sourceFactory(c))return RemoteCaptureCatalog.Search(source,c,path,ct);},ct);if(c!=connection)return;folderContents[path]=files;folderErrors.Remove(path);}
     catch(OperationCanceledException){return;}catch(Exception e){if(c!=connection||closed)return;folderErrors[path]=e.Message;folderContents[path]=new List<Entry>();Error.Text="Couldn't read "+RemoteCapturePaths.Relative(c,path)+": "+e.Message;}
     if(!closed){SyncGrid();UpdateActions();}}}
   // A counter cancelled by a telescope change may exit after new folders were queued for the current connection.
   finally{counting=false;if(!closed&&connection!=null&&pendingCounts.Count>0)CountFolders();else if(!closed&&c==connection)UpdateActions();}
  }
  // Every file the import would take: chosen files plus the contents of chosen folders, without duplicates.
  internal List<Entry> SelectedFiles(){var all=new Dictionary<string,Entry>(StringComparer.OrdinalIgnoreCase);foreach(var e in basket.Values.Where(include))all[e.Path]=e;foreach(var path in folders.Keys){List<Entry> files;if(folderContents.TryGetValue(path,out files))foreach(var e in files.Where(include))all[e.Path]=e;}return all.Values.ToList();}
  int PendingFolders{get{return folders.Keys.Count(p=>!folderContents.ContainsKey(p));}}
  void UpdateActions(){if(ConnectButton==null||ImportButton==null)return;BusyProgress.Visibility=busy?Visibility.Visible:Visibility.Collapsed;ConnectButton.IsEnabled=!busy&&connection==null&&Devices.SelectedItem!=null;FindButton.IsEnabled=!busy;AdvancedButton.IsEnabled=!busy;SearchButton.IsEnabled=SelectButton.IsEnabled=UpButton.IsEnabled=RootButton.IsEnabled=!busy&&connection!=null;Profiles.IsEnabled=Name.IsEnabled=!busy;if(SkipFailed!=null)SkipFailed.IsEnabled=SkipRaster.IsEnabled=!busy;Files.IsEnabled=Devices.IsEnabled=!busy;CancelButton.Visibility=busy?Visibility.Visible:Visibility.Collapsed;CancelButton.Content=connection==null?"Cancel search / connection":"Cancel";bool named=Profiles.SelectedItem is TelescopeProfile&&!string.IsNullOrEmpty(((TelescopeProfile)Profiles.SelectedItem).Id)||!string.IsNullOrWhiteSpace(Name.Text);var chosen=SelectedFiles();int pending=PendingFolders,failed=folders.Keys.Count(p=>folderErrors.ContainsKey(p));ImportButton.IsEnabled=!busy&&connection!=null&&chosen.Count>0&&pending==0&&failed==0&&named;bool watching=connection!=null&&liveActive(connection);LiveButton.IsEnabled=!busy&&connection!=null&&named&&!watching;LiveButton.Content=watching?"Live import underway":"Start live import";ImportButton.Content=pending>0?"Counting files…":chosen.Count==0?"Import selected":"Import "+chosen.Count.ToString("N0")+" file"+(chosen.Count==1?"":"s");LiveButton.Visibility=connection==null?Visibility.Collapsed:Visibility.Visible;ImportButton.Visibility=connection==null?Visibility.Collapsed:Visibility.Visible;LiveScopeText.Text=connection==null?"":watching?"Live import is underway for this telescope. Select files to download alongside it; manage the watcher in Activity.":"Live folder: "+(folder==connection.Folder?"All captures":RemoteCapturePaths.Relative(connection,folder))+" · "+(includeExisting?"Existing and new captures":"New captures only");ImportButton.IsDefault=ImportButton.IsEnabled;ConnectButton.IsDefault=ConnectButton.IsEnabled;ClearButton.IsEnabled=basket.Count+folders.Count>0;
   if(basket.Count+folders.Count==0){SelectionText.Text="Nothing selected";SelectionDetail.Text="Click a file or folder to select it · Ctrl or Shift to add more · Double-click a folder to open it · Esc clears";return;}
   SelectionText.Text=(pending>0?"At least ":"")+chosen.Count.ToString("N0")+" file"+(chosen.Count==1?"":"s")+" · "+ImportWorkflow.Size(chosen.Sum(e=>Math.Max(0,e.Size)));
   var parts=new List<string>();if(folders.Count>0)parts.Add(folders.Count.ToString("N0")+" folder"+(folders.Count==1?"":"s")+" (with subfolders)");if(basket.Count>0)parts.Add(basket.Count.ToString("N0")+" file"+(basket.Count==1?"":"s"));
   SelectionDetail.Text=string.Join(" and ",parts)+" selected"+(pending>0?" · counting "+pending+" folder"+(pending==1?"":"s")+"…":"")+(failed>0?" · couldn't read "+failed+" folder"+(failed==1?"":"s")+"; deselect "+(failed==1?"it":"them")+" to continue":"");}
  void Accept(bool live){if(busy||connection==null)return;try{var selected=Profiles.SelectedItem as TelescopeProfile;var profile=selected!=null&&!string.IsNullOrEmpty(selected.Id)?Util.Deserialize<TelescopeProfile>(Util.Serialize(selected)):new TelescopeProfile{Id=Name.Text.Trim(),SessionIdentity=Name.Text.Trim(),Model=ModelFromDiscovery(device.Name),Camera="Auto"};if(string.IsNullOrWhiteSpace(profile.Id))throw new IOException("Enter a name for this physical telescope.");if((selected==null||string.IsNullOrEmpty(selected.Id))&&saved.Any(p=>p.Id.Equals(profile.Id,StringComparison.OrdinalIgnoreCase)))throw new IOException("That telescope is already saved. Select it above or choose another name.");if(!string.IsNullOrEmpty(profile.RemoteIdentity)&&!string.IsNullOrEmpty(device.Identity)&&profile.RemoteIdentity!=device.Identity)throw new IOException("That saved telescope is linked to another device. Choose a new name for this telescope.");var files=SelectedFiles();if(!live&&(files.Count==0||PendingFolders>0))return;
    if(!NetworkImportNotice(Dialog.Window,live).Show())return;
    var c=Util.Deserialize<RemoteConnection>(Util.Serialize(connection));c.IncludeExisting=includeExisting;c.PollSeconds=poll;c.LimitMB=limit;if(live)c.Folder=folder;profile.SourceMake=c.Kind=="Seestar SMB"?"Seestar":"DWARFLAB";if(!string.IsNullOrEmpty(device.Identity))profile.RemoteIdentity=device.Identity;var request=new RemoteImportRequest{Connection=c,Profile=profile,Files=files,Live=live};string issue=validateRequest==null?null:validateRequest(request);if(issue!=null)throw new IOException(issue);Request=request;Dialog.Window.DialogResult=true;
   }catch(Exception e){Error.Text=e.Message;}}
  static string ModelFromDiscovery(string name){string normalized=(name??"").Replace("S50P","S50 Pro").Replace("S30P","S30 Pro");return TelescopeProfiles.Models.FirstOrDefault(m=>m!="Auto"&&m!="Other"&&normalized.IndexOf(m,StringComparison.OrdinalIgnoreCase)>=0)??"Auto";}
  // Shown before every network import; the advice does not depend on how many files are chosen.
  internal static FormWindow NetworkImportNotice(Window owner,bool live){var d=new FormWindow(owner,"Network import",540,300);d.Text("Import over the network?",true);d.Text("Network imports take longer than a wired connection. For large numbers of files, a wired USB connection is highly recommended.");d.Accept(live?"Start live import":"Import over network",()=>true);return d;}
  async void Advanced(){var d=new FormWindow(Dialog.Window,"Advanced telescope access",650,720);d.Text("Manual access and network options",true);d.Text("Automatic discovery needs no configuration. Use these options for a hidden network, unusual firmware or a custom capture location.");var kind=d.Select("Telescope",new[]{"Seestar","DWARF"},connection==null?manualKind:connection.Kind=="Seestar SMB"?"Seestar":"DWARF");var host=d.Input("Telescope IPv4 address",connection==null?manualHost:connection.Host);var path=d.Input("Storage path (leave blank for default)",connection==null?manualFolder:connection.Folder);var adapter=d.Select("Discovery network",new[]{"All active networks"}.Concat(DiscoveryNetwork.Available().Select(n=>n.Display)).ToArray(),selectedNetwork==null?"All active networks":selectedNetwork.Display);var port=d.Input("DWARF FTP port",ftpPort.ToString());var user=d.Input("DWARF FTP username",ftpUser);d.Text("DWARF FTP password (saved securely for import recovery)");var password=new PasswordBox{Password=ftpPassword};d.Add(password);Action ftpVisibility=()=>{bool ftp=Convert.ToString(kind.SelectedItem)=="DWARF";port.IsEnabled=user.IsEnabled=password.IsEnabled=ftp;};kind.SelectionChanged+=(s,e)=>ftpVisibility();ftpVisibility();var interval=d.Input("Live polling interval (seconds)",poll.ToString());var bandwidth=d.Select("Transfer limit",new[]{"1 MB/s","2 MB/s","5 MB/s","Unlimited"},limit==0?"Unlimited":limit+" MB/s");var existing=d.Check("Also import existing captures when live import starts",includeExisting);d.Text("Seestar uses direct, read-only file access. No Windows guest-access or signing-policy changes are required.");var error=new TextBlock{TextWrapping=TextWrapping.Wrap};d.Add(error);d.Accept("Apply",()=>{try{int p,seconds;if(!int.TryParse(port.Text,out p)||!int.TryParse(interval.Text,out seconds))throw new IOException("Enter whole numbers for port and polling interval.");if(p<1||p>65535||seconds<2||seconds>120)throw new IOException("Use port 1–65535 and a polling interval of 2–120 seconds.");manualKind=Convert.ToString(kind.SelectedItem);manualHost=host.Text.Trim();manualFolder=path.Text.Trim();ftpPort=p;ftpUser=user.Text;ftpPassword=password.Password;poll=seconds;string rate=Convert.ToString(bandwidth.SelectedItem);limit=rate=="Unlimited"?0:double.Parse(rate.Split(' ')[0]);includeExisting=existing.IsChecked==true;selectedNetwork=DiscoveryNetwork.Available().FirstOrDefault(n=>n.Display==Convert.ToString(adapter.SelectedItem));return true;}catch(Exception e){error.Text=e.Message;return false;}});if(!d.Show())return;if(!string.IsNullOrEmpty(manualHost)){var manual=new DiscoveredTelescope{Kind=manualKind=="Seestar"?"Seestar SMB":"DWARF FTP",Host=manualHost,Name=manualKind+" (manual)"};var c=new RemoteConnection{Kind=manual.Kind,Host=manualHost,Folder=manualFolder.Length>0?manualFolder:manual.Kind=="Seestar SMB"?@"\\"+manualHost+@"\EMMC Images":"/",Port=ftpPort,User=ftpUser,Password=ftpPassword,PollSeconds=poll,LimitMB=limit,IncludeExisting=includeExisting};await Connect(manual,c);}}
  internal void PreparePreview(DiscoveredTelescope telescope,RemoteConnection c,IEnumerable<Entry> entries){preview=true;connection=c;device=telescope;folder=c.Folder;ConnectedPanel.Visibility=Visibility.Visible;DiscoveryPanel.Visibility=Visibility.Collapsed;ConnectedText.Text="Connected · "+telescope.Name+" · "+c.Host;ConfigureProfile(telescope);foreach(var entry in entries.Where(e=>!e.Directory&&include(e)))basket[entry.Path]=entry;ShowFiles(entries);UpdateActions();}
  internal bool Show(){return Dialog.Show()&&Request!=null;}
 }
 public partial class MainUi {
  readonly List<RemoteImportSession> remoteSessions=new List<RemoteImportSession>();
  bool NetworkImportBlocked {get{return closing||cancel!=null||dumpChecking||releaseInstalling||usbImportPicking||sourceRemovalConfirming;}}
  static string RemoteEndpoint(RemoteConnection c){return RemoteCapturePaths.LocalFolder(c)?c.Kind+"|"+Path.GetFullPath(c.Folder).TrimEnd('\\','/').ToLowerInvariant():c.Kind+"|"+c.Host.ToLowerInvariant()+"|"+(c.Kind=="Seestar SMB"?c.SmbPort:c.Port);}
  bool HasLiveImport(RemoteConnection c){return remoteSessions.Any(s=>s.Request.Live&&RemoteEndpoint(s.Request.Connection)==RemoteEndpoint(c));}
  string ValidateRemoteRequest(RemoteImportRequest request){
   if(request.Live&&HasLiveImport(request.Connection))return RemoteCapturePaths.LocalFolder(request.Connection)?"This folder is already being watched. Stop its watcher in Activity first.":"Live import is already underway for this telescope. Select files to import alongside it, or stop its watcher in Activity first.";
   if(RemoteCapturePaths.LocalFolder(request.Connection)&&remoteSessions.Any(s=>RemoteCapturePaths.LocalFolder(s.Request.Connection)&&(Util.Within(s.Request.Connection.Folder,request.Connection.Folder)||Util.Within(request.Connection.Folder,s.Request.Connection.Folder))))return "Another watcher already covers part of this folder. Stop it in Activity, or choose a separate folder.";
   var endpoint=RemoteEndpoint(request.Connection);
   if(remoteSessions.Any(s=>s.Request.Profile.Id.Equals(request.Profile.Id,StringComparison.OrdinalIgnoreCase)&&RemoteEndpoint(s.Request.Connection)!=endpoint))return "This saved telescope is importing from another device. Choose a different saved telescope or give this device its own name.";
   if(remoteSessions.Any(s=>RemoteEndpoint(s.Request.Connection)==endpoint&&!s.Request.Profile.Id.Equals(request.Profile.Id,StringComparison.OrdinalIgnoreCase)))return "This device is already importing as another saved telescope. Use the same saved telescope shown in Activity.";
   return null;
  }
  void SaveRemoteImportFilters(RemoteImportFilters filters){
   if(settings.IgnoreFailed==filters.IgnoreFailed&&settings.IgnoreRasterImports==filters.IgnoreRaster)return;settings.IgnoreFailed=filters.IgnoreFailed;settings.IgnoreRasterImports=filters.IgnoreRaster;SaveSettings();((CheckBox)Window.FindName("IgnoreFailedCheck")).IsChecked=settings.IgnoreFailed;
   // Matches Import preferences saved from this dialog: a folder scan built with the old filters is discarded.
   if(remoteSessions.Count==0&&plan!=null){plan=null;FilterImports();L("StatusLabel").Text="Import option saved. Scan the source folder again to apply it.";}
  }
  void InitializeRemoteImport(){B("RemoteTelescopeButton").Click+=(s,e)=>OpenRemoteImport();B("RemoteLiveStatusButton").Click+=(s,e)=>OpenActivity();B("WatchFolderButton").Click+=(s,e)=>OpenLocalWatch();}
  async void OpenRemoteImport(){
   if(NetworkImportBlocked||repo==null)return;RemoteImportRequest request=null;usbImportPicking=true;SetBusy(true);
   try{var dialog=new RemoteImportDialog(Window,settings.Telescopes,SelectedScope,new RemoteImportFilters{IgnoreFailed=settings.IgnoreFailed,IgnoreRaster=settings.IgnoreRasterImports,Changed=SaveRemoteImportFilters},isLiveActive:HasLiveImport,validate:ValidateRemoteRequest);if(dialog.Show())request=dialog.Request;}
   finally{usbImportPicking=false;SetBusy(false);}if(request==null||repo==null||closing)return;
   try{await StartRemoteImport(request);}catch(Exception error){MessageBox.Show(Window,error.Message,"Telescope import could not start",MessageBoxButton.OK,MessageBoxImage.Warning);}
  }
  internal Task StartRemoteImport(RemoteImportRequest request,Func<RemoteConnection,ISource> factory=null,ImportResumeRecord recovery=null){
   if(NetworkImportBlocked||repo==null)throw new InvalidOperationException("Wait for the current operation before starting a telescope import.");string issue=ValidateRemoteRequest(request);if(issue!=null)throw new IOException(issue);
   var previous=TelescopeProfiles.Find(settings,request.Profile.Id);if(previous!=null)settings.Telescopes.Remove(previous);settings.Telescopes.Add(request.Profile);settings.SelectedTelescope=request.Profile.Id;ReloadScopes(request.Profile.Id,true);
   ((CheckBox)Window.FindName("DeleteOriginalsCheck")).IsChecked=false;C("ImportSolveMode").SelectedItem="Off";C("ImportRotationMode").SelectedItem="Off";((TabControl)Window.FindName("MainTabs")).SelectedIndex=1;
   bool local=RemoteCapturePaths.LocalFolder(request.Connection);if(local)RemoteCapturePaths.CheckWatchedFolder(request.Connection,repo.Root);
   string cache=Path.Combine(Path.GetDirectoryName(config),"RemoteDownloads");if(remoteSessions.Count==0){T("SourceBox").Text=local?request.Connection.Folder:cache;plan=null;BeginLive(true);}SaveSettings();
   var record=recovery??RemoteImportRecord(request);record.State="Running";ResumeStore.Save(record);
   var session=new RemoteImportSession{Request=request,Record=record,Activity=AddActivity(record.Title,true)};
   session.Activity.LiveImport=request.Live;session.Activity.ProcessContext=request.Profile.Id+" · "+RemoteCapturePaths.SourceLabel(request.Connection);session.Activity.NetworkImport=true;session.Activity.RepositoryRoot=repo.Root;session.Activity.CancelLabel=local?"Stop watching":request.Live?"Stop live import":"Cancel download";
   session.Activity.Pause=()=>PauseRemoteImport(session);session.Activity.Cancel=()=>{session.Record.State="Canceled";session.Cancellation.Cancel();session.Activity.Canceled=true;session.Activity.Status="Stopping this telescope import; completed copies are retained…";};remoteSessions.Add(session);SetBusy(true);
   session.Work=RunRemoteSession(session,repo,cache,record.Workers,record.IgnoreFailed,record.IgnoreRaster,factory);return session.Work;
  }
  async Task RunRemoteSession(RemoteImportSession session,Repository repository,string cache,int workers,bool ignoreFailed,bool ignoreRaster,Func<RemoteConnection,ISource> factory){
   var request=session.Request;var token=session.Cancellation.Token;string status=null;bool canceled=false;
   Action<ProgressInfo> progress=p=>session.Latest=p;
   Action<RemoteArchiveResult> completed=result=>{session.Imported+=result.Archive.Import.Imported;session.Duplicates+=result.Archive.Import.Duplicates;if(result.Archive.Import.Failed+result.Downloads.Errors.Count>0)session.Record.State="Interrupted";if(result.Archive.Import.Errors.Count+result.Archive.Import.Warnings.Count>0){session.NeedsReview=true;session.Report=(session.Report??"")+result.Report+Environment.NewLine;}};
   try{status=await Task.Run(()=>{
    if(request.Live){RemoteLiveImport.Run(repository,request.Profile,request.Connection,cache,workers,token,progress,LiveFrame,null,ignoreFailed,ignoreRaster,factory,completed,session.Record.LiveState,state=>{session.Record.LiveState=state;ResumeStore.Save(session.Record);});return RemoteCapturePaths.LocalFolder(request.Connection)?"Stopped watching the folder.":"Live import stopped.";}
    var result=RemoteArchiveImport.Run(repository,request.Profile,request.Connection,request.Files,cache,workers,token,progress,LiveFrame,null,ignoreFailed,ignoreRaster,factory);completed(result);return result.Summary;
   });}
   catch(OperationCanceledException){canceled=true;status="Stopped. "+session.Imported+" imported; "+session.Duplicates+" already present. Completed copies retained; "+(RemoteCapturePaths.LocalFolder(request.Connection)?"originals in the watched folder":"telescope originals")+" unchanged.";}
   catch(Exception error){session.Activity.Failed=true;session.NeedsReview=true;session.Report=(session.Report??"")+error.Message;status="Import could not finish: "+error.Message;}
   finally{
    LiveTick(true);session.Clock.Stop();var entry=session.Activity;entry.Running=false;entry.Cancel=null;entry.Pause=null;entry.Canceled=canceled;entry.Status=status;entry.DurationSeconds=session.Clock.Elapsed.TotalSeconds;entry.ProcessOutcome=session.Imported+" imported · "+session.Duplicates+" duplicates";if(entry.Progress!=null){entry.Progress.Finished=true;entry.Progress.ElapsedSeconds=entry.DurationSeconds.Value;entry.Progress.RemainingSeconds=null;}entry.NeedsReview=session.NeedsReview;entry.Report=session.Report;entry.ReportTitle=(RemoteCapturePaths.LocalFolder(request.Connection)?"Folder watch report · ":"Telescope import report · ")+request.Profile.Id;
    remoteSessions.Remove(session);session.Cancellation.Dispose();if(remoteSessions.Count==0){plan=new ImportPlan{Source=RemoteCapturePaths.LocalFolder(request.Connection)?request.Connection.Folder:cache,Frames=importRows.ToList()};importLive=false;latestProgress=null;((ProgressBar)Window.FindName("ProgressBar")).IsIndeterminate=false;}
    FinishImportRecord(session.Record,entry,!entry.Failed&&!canceled,canceled);SetBusy(false);Refresh();L("StatusLabel").Text=remoteSessions.Count==0?entry.Status:remoteSessions.Count+" telescope imports underway. See Activity for each telescope.";NotifyActivity(entry);if(closing&&remoteSessions.Count==0)Window.Close();
   }
  }
  void StopRemoteImports(){foreach(var session in remoteSessions.ToList()){session.Activity.Canceled=true;session.Activity.Cancel();}RenderActivity();}
  void UpdateRemoteImportStatus(){
   var live=remoteSessions.Where(s=>s.Request.Live).ToList();var indicator=B("RemoteLiveStatusButton");indicator.Visibility=live.Count==0?Visibility.Collapsed:Visibility.Visible;
   indicator.Content=live.Count==1?"● Live import underway":"● "+live.Count+" live imports underway";indicator.ToolTip=string.Join("\n",live.Select(s=>s.Request.Profile.Id+" · "+(RemoteCapturePaths.LocalFolder(s.Request.Connection)?"Watching "+s.Request.Connection.Folder:s.Request.Connection.Host+" · "+s.Request.Connection.Folder)))+"\nView Activity to stop individual imports.";
   B("RemoteTelescopeButton").IsEnabled=repo!=null&&!NetworkImportBlocked&&(!operationBusy||remoteSessions.Count>0);B("WatchFolderButton").IsEnabled=B("RemoteTelescopeButton").IsEnabled;B("CancelButton").Content=remoteSessions.Count>0?"Stop all telescope imports":"Cancel";
   B("PauseImportButton").Visibility=remoteSessions.Count>0||foregroundImportRecord!=null?Visibility.Visible:Visibility.Collapsed;B("PauseImportButton").Content=remoteSessions.Count>1?"Pause all imports":"Pause import";
  }
  void TickRemoteImports(){
   var estimates=new List<string>();var transfers=new List<ProgressInfo>();
   foreach(var session in remoteSessions){var p=session.Latest;if(p==null)continue;var metrics=p.LiveMetrics;if(metrics!=null)p=metrics.Progress(false);p.ElapsedSeconds=session.Clock.Elapsed.TotalSeconds;session.Activity.Progress=p;
    session.Activity.Status=session.Record.State=="Pausing"?"Pausing safely; verified downloads are retained…":session.Activity.Canceled?"Stopping this telescope import…":(p.Stage==null?"":p.Stage+": ")+p.Text;
    session.Activity.ProcessOutcome=session.Imported+" imported · "+session.Duplicates+" duplicates";
    estimates.Add(session.Request.Profile.Id+": "+RemoteEstimateLabel(p));if(p.Stage!="Live import")transfers.Add(p);
    ActivityCard card;if(activityCards.TryGetValue(session.Activity,out card)){card.Status.Text=session.Activity.Status;card.Rate.Text=ProcessParameters(session.Activity);card.Bar.IsIndeterminate=!settings.ReducedMotion&&!p.TotalKnown&&!p.Finished;card.Bar.Value=Math.Max(0,Math.Min(1,p.ProgressFraction));}
   }
   if(remoteSessions.Count>0){L("StatusLabel").Text=remoteSessions.Count+" telescope import"+(remoteSessions.Count==1?"":"s")+" underway. Connect to select more files or add another telescope; view Activity for progress.";L("RateLabel").Text=estimates.Count==0?"Preparing telescope imports…":string.Join(" · ",estimates);var bar=(ProgressBar)Window.FindName("ProgressBar");bar.IsIndeterminate=!settings.ReducedMotion&&transfers.Any(p=>!p.TotalKnown);bar.Maximum=1;bar.Value=transfers.Count==0?0:transfers.Average(p=>p.ProgressFraction);}
  }
  static string RemoteEstimateLabel(ProgressInfo p){return p.Stage=="Live import"?"Watching for captures":p.Stage=="Scanning folder"?"Checking folder":p.RemainingSeconds.HasValue?"ETA ~"+EtaEstimate.Format(p.RemainingSeconds.Value):p.Stage=="Downloading from telescope"?"Starting transfer":p.Stage??"Preparing";}
 }
